 const{session,can,notify}=useApp();const router=useRouter();const queryClient=useQueryClient();
 const navAppearance=useNavigationAppearance();
 const[quickOpen,setQuickOpen]=useState(false),[profileMenuOpen,setProfileMenuOpen]=useState(false),[noticePopup,setNoticePopup]=useState<Row|null>(null);
